    {
      "kind": "rule",
      "id": "REG.STIMULUS_DTP.ELIGIBILITY",
      "label": "Determine permanent employee eligibility for the 2025 DTP incentive",
      "label_id": "Penentuan kelayakan pegawai tetap untuk insentif DTP 2025",
      "valid_from": "2025-01-01",
      "valid_until": "2025-12-31",
      "recorded_on": "2025-02-04",
      "fields": [
        {
          "name": "layer",
          "value": "regulation"
        },
