          "page": 8,
          "quote": "Ditetapkan di Jakarta\npada tanggal 4 Februari 2025"
        }
      ]
    },
    {
      "kind": "rule",
      "id": "REG.DTP.LABOR_INTENSIVE_EMPLOYEE_REFUND",
      "label": "Exclude excess labor-intensive industry DTP from the employee's annual refund",
      "label_id": "Mengecualikan kelebihan DTP industri padat karya dari pengembalian tahunan kepada pegawai",
      "valid_from": "2025-01-01",
      "valid_until": "2025-12-31",
      "recorded_on": "2025-02-04",
      "fields": [
        {"name": "layer", "value": "regulation"},
        {"name": "modality", "value": "mandatory"},
        {"name": "scope", "value": "year"},
        {"name": "produces", "value": "refund_to_employee"},
        {
          "name": "condition",
          "value": "sum_periods_before_final('labor_intensive_dtp_amount') > 0"
